'handover':()=>modal('人工接管',`${note('人工接管保留任务、材料、证据和已发生的执行记录。')}<div class="mt16">${kv([['目标','排查报表差异'],['已完成','材料解析、代码定位'],['未完成','数据核对、验证'],['待确认','原始筛选状态'],['资源权限','继承原问题范围'],['交接人','系统负责人（示例）']])}</div>`,b('取消','close')+b('记录接管','handover-save','primary')),
