'stop-task':()=>modal('停止此任务？',`<p class="small">${esc(S.selectedTask)} 将进入停止中，等待执行器确认；不会伪造停止成功。</p>`,b('取消','close')+b('模拟停止请求','stop-task-confirm','danger')),
