'node-up':()=>moveNode(-1),'node-down':()=>moveNode(1),
'remove-node':()=>{if(S.nodes.length<=2){toast('至少保留两个节点。');return}S.nodes=S.nodes.filter(n=>n.id!==S.selectedNode);S.selectedNode=S.nodes[0].id;S.workflowDraft=true;persist();render();toast('草稿节点已移除，发布前需重新校验。')},
