'configure-assistant':el=>configModal(el.dataset.name+' · 配置',[['显示名称','name',null,el.dataset.name],['默认流程','workflow',['报表差异核对 v1.3','逻辑解释 v1.0','测试数据准备 v1.1'],'报表差异核对 v1.3'],['系统范围','system',['B2B','WMS'],'B2B'],['环境范围','env',['测试','预发','测试与预发'],'测试与预发'],['模型选择权','modelChoice',['继承后台配置','允许授权用户覆盖'],'继承后台配置'],['单任务预算','budget',null,'30']],'assistant.'+el.dataset.name),
