'add-mcp':()=>configModal('新增 MCP 连接',[['连接名称','name',null,'新工具连接'],['传输方式','transport',['stdio','Streamable HTTP'],'Streamable HTTP'],['地址（演示）','address',null,'https://mcp.example.invalid'],['凭据引用','secret',null,'secret://demo/mcp-new'],['环境范围','env',['测试','预发'],'测试'],['工具策略','policy',['允许名单 / 默认拒绝'],'允许名单 / 默认拒绝']],'mcp.new'),
'mcp-config':el=>configModal(el.dataset.name+' · 配置',[['连接名称','name',null,el.dataset.name],['工具允许名单','tools',null,'db.schema, db.query_readonly'],['凭据引用','secret',null,'secret://demo/mcp'],['请求超时 / 秒','timeout',null,'30'],['最大返回行','rows',null,'5000'],['写入策略','write',['默认拒绝','固定计划审批'],'固定计划审批']],'mcp.'+el.dataset.name),
